def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Bucket-queue implementation
    # Each bucket is a priority queue
    # bucket[i] stores nodes with current shortest distance i
    max_distance = 100 * 100  # maximum possible distance (100 nodes * 100 weight)
    buckets = [[] for _ in range(max_distance + 1)]
    dist = [-1] * n
    dist[s] = 0
    buckets[0].append(s)

    while buckets[0]:
        # Extract node with smallest distance
        u = buckets[0].pop(0)
        for v, w in adj[u]:
            if dist[v] == -1 or dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                # Move v from its current bucket to the new bucket
                if dist[v] <= max_distance:
                    if buckets[dist[v]]:
                        heapq.heappush(buckets[dist[v]], v)
                    else:
                        buckets[dist[v]] = [v]
        # Remove the bucket if it's empty
        if not buckets[0]:
            del buckets[0]

    return dist[t] if dist[t] != -1 else -1

